use vstd::prelude::*;

verus! {
    // all_prefixes: given s: Vec<char>, build a Vec of its nonempty prefixes
    // ensures that result.len() == s.len(),
    // and for each i < s.len(), result[i] is exactly s[0..i+1].
    fn all_prefixes(s: Vec<char>) -> (result: Vec<Vec<char>>)
        ensures
            // same number of prefixes as the length of s
            result@.len() == s@.len(),
            // for each i, the i-th prefix equals s[0..i+1]
            forall |i: nat|
                i < s@.len() ==>
                    (result@[i])@ == s@.slice(0, i + 1),
    {
        let n = s.len();
        let mut result: Vec<Vec<char>> = Vec::new();
        let mut i: usize = 0;
        // Outer loop: build prefixes of length 1,2,…,n
        while i < n
            invariant
                i <= n,
                result.len() == i,
                // for all already built j < i, result[j] is s[0..j+1]
                forall |j: nat|
                    j < i ==>
                        (result@[j])@ == s@.slice(0, j + 1),
            decreases n - i,
        {
            // build the next prefix of length i+1
            let mut prefix: Vec<char> = Vec::new();
            let mut k: usize = 0;
            // Inner loop: copy s[0], s[1], …, s[i] into prefix
            while k < i + 1
                invariant
                    k <= i + 1,
                    prefix.len() == k,
                    // prefix[0..k] matches s[0..k]
                    forall |j: nat|
                        j < k ==>
                            prefix@[j] == s@[j],
                decreases (i + 1) - k,
            {
                let c = s.get(k).unwrap(); // safe because k < i+1 <= n = s.len()
                prefix.push(c);
                k += 1;
            }
            // Now prefix.len() == i+1 and prefix@[j] == s@[j] for j < i+1
            result.push(prefix);
            // Prove that result[i] is exactly s[0..i+1]
            assert((result@[i])@ == s@.slice(0, i + 1));
            i += 1;
        }
        result
    }
}

